module gwx_rom32_bank #(parameter FILE="")(input wire clk,en,input wire[8:0]addr,output reg[31:0]q);
 reg[31:0]mem[0:511];initial $readmemh(FILE,mem);
 always @(posedge clk)if(en)q<=mem[addr];
endmodule
module gwx_rom36_bank #(parameter FILE="")(input wire clk,en,input wire[8:0]addr,output reg[35:0]q);
